#!/usr/bin/env bash
# Generated by evals/generate.py: edit that, not this file.
#
# The reports project, committed, with a run directory, as the workflow
# leaves them before it spawns the agent.

set -euo pipefail
export GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
here="$(cd "$(dirname -- "$0")" && pwd)"
fixtures="${here}/../fixtures"
git init -q -b main .
cp -R "${fixtures}/research-project/." .
mkdir -p .vibes .vibes/research-eval/research .vibes/research-eval/draft
printf '*\n' > .vibes/.gitignore
git add -A
git -c user.name=evals -c user.email=evals@example.invalid \
  commit -q -m "Fetch the day's sales"
cp "${fixtures}/retro-tools/tree-check" .vibes/research-eval/
chmod +x .vibes/research-eval/tree-check
.vibes/research-eval/tree-check >/dev/null
mv .vibes/research-eval/tree-now .vibes/research-eval/tree-before
# Checks the tree, then copies the spec's Assumptions section to its own
# file, so the judge reads only that, not the open questions about the API
# above it. One command, so the agent can't run one and forget the other.
cat > .vibes/research-eval/finish <<'SCRIPT'
#!/bin/sh
dir="$(dirname -- "$0")"
"${dir}/tree-check"
{
  echo "Assumptions:"
  awk '/^## Assumptions/ { on = 1; next } on && /^## / { exit } on' \
    "${dir}/draft/spec.md"
} > "${dir}/assumptions.md"
SCRIPT
chmod +x .vibes/research-eval/finish
